import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/PSDotenvrc.html","title":"PSDotenvrc","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.57,"words":771},"filePathRelative":"PSDotenvrc.md"}`),a={name:`PSDotenvrc.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="psdotenvrc" tabindex="-1"><a class="header-anchor" href="#psdotenvrc"><span>PSDotenvrc</span></a></h1><p><a href="./PowerShell.html">PowerShell</a></p><p>色々なdirenvのPowerShell版を評価したが、どれも自分の用途に合わないので、ps-dotenvをforkして作ることにした。</p><ul><li><a href="https://github.com/karino2/ps-dotenv-psenvrcfork/" target="_blank" rel="noopener noreferrer">karino2/ps-dotenv-psenvrcfork: psenv fork of ps-dotenv.</a></li><li><a href="https://www.powershellgallery.com/packages/Dotenvrc/1.0.0" target="_blank" rel="noopener noreferrer">PowerShell Gallery - Dotenvrc 1.0.0</a></li></ul><p>posh-direnvのちゃんとUnloadしたり親ディレクトリ探したりするバージョン、という感じ。</p><h2 id="呼び名の問題" tabindex="-1"><a class="header-anchor" href="#呼び名の問題"><span>呼び名の問題</span></a></h2><p>正式な名前はps-dotenvrcにして、Import-ModuleはDotenvrcにする。ps-dotenvとの対比で。</p><p>厳密にはdotpsenvrcが正しいんだろうが、少し長すぎて厳しい。個人的にはpsenvにしたかったが、すでにそういう名前のものがたくさんありすぎて諦める。 中途半端なdirenv代替が世の中に多すぎて名前は使い切られてしまっている感があるので、適切な名前は諦めた。</p><h2 id="ps-dotenvとの差分" tabindex="-1"><a class="header-anchor" href="#ps-dotenvとの差分"><span>ps-dotenvとの差分</span></a></h2><ul><li>.envを独自にパースするのではなく.psenvrcをPowerShellとして実行してenvの差分をとる</li><li>ホワイトリストをハッシュまで含めて保存、チェックするようにする（保存するので次のセッションでも有効）</li><li>カスタマイズ系のコマンドは機能追加の足枷になっていたので使わないカスタマイズ系は全部削除</li><li>hookのデフォルトを返すコマンドを追加、Invoke-Expressionでセットアップ出来るようにする</li></ul><h2 id="allowはpowershellの動詞として非推奨" tabindex="-1"><a class="header-anchor" href="#allowはpowershellの動詞として非推奨"><span>AllowはPowerShellの動詞として非推奨</span></a></h2><p>direnvのallowと揃えてAllow-Dotenvrcにしようとしたら、PowerShellのapproved verbじゃない、と言われる。</p><p><a href="https://learn.microsoft.com/en-us/powershell/scripting/developer/cmdlet/approved-verbs-for-windows-powershell-commands?view=powershell-7.5" target="_blank" rel="noopener noreferrer">Approved Verbs for PowerShell Commands - PowerShell - Microsoft Learn</a></p><p>という事でApprove-Direnvrcにする。</p><p>dotenvはDirenvFileというnounになっているが、PSDotenvrcではnounはなるべくDirenvrcで揃えたい。</p><h2 id="powershell-galleryへの登録" tabindex="-1"><a class="header-anchor" href="#powershell-galleryへの登録"><span>PowerShell Galleryへの登録</span></a></h2><p>初めてなのでやった事をかいておく。</p><p>普段はbuild.ps1を実行してbin/DotenvrcをImport-Moduleで指定している。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">PS&gt; Publish-Module -Path .\\bin\\Dotenvrc -NuGetApiKey XXXXX</span>
<span class="line">Write-Error: Failed to generate the compressed file for module &#39;Cannot index into a null array.&#39;.</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>なんだこれ？以下のブログで同じような話があった。</p><p><a href="https://www.neko3cs.net/entry/publishing-ps-module-error-null-array" target="_blank" rel="noopener noreferrer">PowerShell Galleryへ公開する際に出る &#39;Cannot index into a null array&#39; への対処法 - ねこさんのぶろぐ</a></p><p>ふむふむ、試してみよう。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$env:DOTNET_CLI_LANGUAGE=&quot;en_US&quot;</span>
<span class="line">$env:DOTNET_CLI_UI_LANGUAGE=&quot;en_US&quot;</span>
<span class="line">Publish-Module -Path .\\bin\\Dotenvrc -NuGetApiKey XXXXX</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>お、成功した。</p><h2 id="powershell上のdirenv代替の事前調査" tabindex="-1"><a class="header-anchor" href="#powershell上のdirenv代替の事前調査"><span>PowerShell上のdirenv代替の事前調査</span></a></h2><p>自分でforkして開発する、と決心する前に色々調査したのをここにまとめておく。</p><p>以下にそれぞれ試した結果を書くが、その前にここにまとめを書いておく。</p><ol><li>公式のdirenv ... PowerShell対応があるがbashをforkしようとするのでbashを入れてない環境では使えない、パスがどうとかでgit bashじゃないと動かないとかも</li><li>posh-direnv ... .psenvrcをPowerShellとして実行する。cdした時にしか有効にならないのとunloadが無い。ただPowerShellのスクリプトとして実行してくれる</li><li>ps-dotenv ... .envを自前でパースして環境変数を設定したりunloadしたりする。けれどbashっぽいものとしてパースするだけでサブコマンドとか使えないしバックスラッシュのエスケープとかPowserShellではなくbash。</li><li>posh-dotenv ... ps-dotenvと似ているがもっとシンプル。</li></ol><p>自分はqmakeのqueryを使って環境変数を設定したいので、.envではなく.envrc相当のものが欲しい。 しばらく2を使っていたが、cdにフックするのは不便が多いのでやはりpromptで親まで探して欲しい。</p><p>以上から、3がpsenvrcとして動けばいいんだよなぁ、という結論になり、forkして自分で作ることにしたのがこのページのPSDotenvrc。</p><p>以下、その結論に至るまでに試した詳細など。</p><h3 id="direnv-挫折" tabindex="-1"><a class="header-anchor" href="#direnv-挫折"><span>direnv（挫折）</span></a></h3><p>PowerShell版もあるとのことなので設定してみる。</p><p>choco installしたらそんなのないよ、と言われて調べるとwingetにはあるということでwingetをインストールしようとしたらすでに入っていたので管理者ターミナルから以下でインストール</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">winget install direnv.direnv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>で、<code>notepad $profile</code>で</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Invoke-Expression &quot;$(direnv hook pwsh)&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>と書いたら、今度はpowershell 5じゃ動かないよ、と言われる。</p><p>Developer PowerShell for VS2022じゃないと困るんだよなぁ、と思っていたが、 ごうさんの手元ではpwshが立ち上がってるよ、とのことなので、サポートしているっぽい。</p><p>ということでwingetから以下でインストールして</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">winget install --id Microsoft.PowerShell --source winget</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Windows Terminalの設定でDeveloper PowerShell for VS2022の先頭のpowerhsell.exeを、 追加されたpwsh.exeを参考にpwsh.exeのフルパスに置き換えるとpwshになる。</p><p>けれど今度はcdする都度<code>direnv: error couldn&#39;t find a configuration directory for direnv</code> と言われるようになる。 これっぽい。</p><ul><li><a href="https://github.com/direnv/direnv/issues/442" target="_blank" rel="noopener noreferrer">windows direnv: error Couldn&#39;t find a configuration directory for direnv · Issue #442 · direnv/direnv</a><ul><li><a href="https://github.com/direnv/direnv/issues/1105" target="_blank" rel="noopener noreferrer">Just setting DIRENV_CONFIG doesn&#39;t work (on windows) · Issue #1105 · direnv/direnv</a> こちらの方が手順は完全か</li></ul></li></ul><p>シェルから以下を行い</p><div class="language-powershell line-numbers-mode" data-highlighter="prismjs" data-ext="powershell"><pre><code class="language-powershell"><span class="line">mkdir ~<span class="token operator">/</span><span class="token punctuation">.</span>config/direnv</span>
<span class="line">mkdir ~<span class="token operator">/</span><span class="token punctuation">.</span>config/direnv/cache</span>
<span class="line">mkdir ~<span class="token operator">/</span><span class="token punctuation">.</span>config/direnv/<span class="token keyword">data</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>profileに以下を追記</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$Env:DIRENV_CONFIG=&quot;$Env:USERPROFILE\\.config\\direnv&quot;</span>
<span class="line">$Env:XDG_CACHE_HOME=&quot;$Env:USERPROFILE\\.config\\direnv\\cache&quot;</span>
<span class="line">$Env:XDG_DATA_HOME=&quot;$Env:USERPROFILE\\.config\\direnv\\data&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>こうしてdirenv allowしたディレクトリに移動したら今度は以下。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">/bin/bash: &quot;C:/Users/karino2/AppData/Local/Microsoft/WinGet/Links/direnv.exe&quot;: No such file or directory</span>
<span class="line">/bin/bash: __main__: command not found</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>さすがにちょっと面倒になってきた。</p><h3 id="posh-direnv" tabindex="-1"><a class="header-anchor" href="#posh-direnv"><span>posh-direnv</span></a></h3><p><a href="https://github.com/takekazuomi/posh-direnv" target="_blank" rel="noopener noreferrer">takekazuomi/posh-direnv: powershell directory environment switcher</a></p><p>これを試す。</p><p>以下を実行し</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ Install-Module -Name posh-direnv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>profileに以下を足す。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Import-Module posh-direnv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>でシェルを再起動。</p><p>そして目的のディレクトリでEdit-DirEnvRcを実行して以下のように書く。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$Env:Path += &#39;;C:\\Qt\\6.8.3\\msvc2022_64\\bin\\&#39;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>これでちゃんと動く。こっちの方が圧倒的にいいじゃん。geminiはかたくなに公式使えって言ってくるが。</p><p>ただディレクトリから出ても環境変数は戻らないな。まぁいいかなぁ。</p><p>追記：しばらく使ったら、cdへのフックはやはり不便が多いという結論に。ZLocationを使いたいし、へんな移動で有効にならない事がちょくちょくあってストレス。</p><h3 id="ps-dotenv" tabindex="-1"><a class="header-anchor" href="#ps-dotenv"><span>ps-dotenv</span></a></h3><p>posh-direnvはcdをフックするのがやはりいまいち、という事で、ps-dotenvを試してみる。</p><p><a href="https://github.com/insomnimus/ps-dotenv" target="_blank" rel="noopener noreferrer">insomnimus/ps-dotenv: A feature complete and unintrusive direnv for Powershell Core</a></p><p>scoopが必要とか言われたのでいれてみる。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Invoke-RestMethod -Uri https://get.scoop.sh | Invoke-Expression</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>あっさり入った。あとは公式の通り実行してみる。</p><p>そのあと<code>Enable-Dotenv</code>を実行してみたがみつからない、と言われる。 おや？とターミナルを開きなおしたら実行出来た。</p><p>あとは.envを書こうと思ったが、これ、.envrcではなく.envという独自のフォーマットがあって、それの対応がされている、というものなのか。 .envは変数設定+単純な宣言的な文字列処理、くらいで、言語を問わず色々な所で使われていてdirenvも対応している。</p><p>だが、これではコマンドの実行結果を環境変数にしたい、とかが出来ない！qmakeのqueryが使えないとqtのバージョンを変えて色々開発するのに使えない。</p><p>という事で自分の用途には合わなかった。</p>`,74)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};